(() => {
  const $=id=>document.getElementById(id);
  const roots={notes:'notes-root',research:'research-root'};
  let state=null,loadSerial=0,uploadBusy=false,folderBusy=false,mode='create',plan=null;
  const form=$('folder-form'),dialog=$('folder-editor');
  function locationState(){const u=new URL(location.href);const section=u.searchParams.get('section')==='research'?'research':'notes';return {section,folder:u.searchParams.get('folder')||roots[section]};}
  function route(section,folder){return '/archive?'+new URLSearchParams({section,folder});}
  function el(tag,text,className){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(className)e.className=className;return e;}
  async function api(path,options={}){const response=await fetch(path,{cache:'no-store',...options});let data;try{data=await response.json()}catch{throw Error('连接中断，请重试。')}if(!response.ok)throw Error(data.error||'操作失败，请重试。');return data;}
  function jsonOptions(method,body){return {method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)};}
  function bytes(value){if(value===0)return '0 B';if(value<1024)return value+' B';if(value<1048576)return (value/1024).toFixed(1)+' KiB';return (value/1048576).toFixed(1)+' MiB';}
  function icon(folder){const div=el('span',undefined,'entry-icon');div.innerHTML=folder?'<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M3 9V6h10l3 4h13v17H3z"/><path d="M3 10h13"/></svg>':'<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M7 3h12l6 6v20H7z"/><path d="M19 3v7h6M11 16h10M11 21h8"/></svg>';return div;}
  function render(data){state=data;const {section}=locationState();for(const s of ['notes','research']){const tab=$(s+'-tab');if(s===section)tab.setAttribute('aria-current','page');else tab.removeAttribute('aria-current');}
    $('folder-title').textContent=data.folder.name;$('folder-description').textContent=data.folder.description||'暂未填写简介。';document.title=data.folder.name+' · 研究与学习';
    $('manage-tools').hidden=!data.canEdit;$('edit-folder').hidden=!data.canEdit;$('upload-hint').hidden=!data.canEdit;
    const crumb=$('breadcrumbs');crumb.replaceChildren();data.breadcrumbs.forEach((item,index)=>{if(index)crumb.append(el('span','/'));if(index===data.breadcrumbs.length-1){const text=el('span',item.name);text.setAttribute('aria-current','location');crumb.append(text)}else{const a=el('a',item.name);a.href=route(section,item.id);crumb.append(a)}});
    const folders=data.entries.filter(x=>x.kind==='folder'),files=data.entries.filter(x=>x.kind==='file');$('entry-count').textContent=folders.length+' 个目录 · '+files.length+' 个文件';
    const entries=$('entries');entries.replaceChildren();entries.setAttribute('aria-busy','false');for(const item of [...folders,...files]){const row=el('article',undefined,'entry');row.append(icon(item.kind==='folder'));const main=el('div');const a=el('a',item.name,'entry-title');a.href=item.kind==='folder'?route(section,item.id):'/api/archive/files/'+item.id;if(item.kind==='file')a.setAttribute('download',item.name);main.append(a);if(item.description)main.append(el('p',item.description,'entry-description'));row.append(main);const meta=el('div',undefined,'entry-meta');meta.append(el('span',item.kind==='folder'?item.child_count+' 项内容':bytes(item.size)));if(item.kind==='file'){const download=el('a','下载原文件','download-link');download.href=a.href;download.setAttribute('download',item.name);meta.append(download)}row.append(meta);entries.append(row)}if(!data.entries.length){const empty=el('div',undefined,'empty-state');empty.append(el('strong','这个目录还是空的'),el('span',data.canEdit?'可以新建子目录，或上传文件与文件夹。':'这里还没有资料。'));entries.append(empty)}
  }
  async function load(){const ticket=++loadSerial;const target=locationState();$('archive-status').textContent='正在读取…';$('entries').setAttribute('aria-busy','true');$('manage-tools').hidden=true;$('edit-folder').hidden=true;try{let data=await api('/api/archive?'+new URLSearchParams(target));if(!data.initialized&&data.canEdit){await api('/api/archive/init',{method:'POST'});data=await api('/api/archive?'+new URLSearchParams(target))}if(ticket!==loadSerial)return;if(!data.initialized){state=null;$('folder-title').textContent=target.section==='notes'?'学习笔记':'研究进展';$('entries').replaceChildren(el('div','资料目录待建立。','empty-state'));$('entries').setAttribute('aria-busy','false');$('archive-status').textContent='';return}render(data);$('archive-status').textContent='';}catch(error){if(ticket!==loadSerial)return;state=null;$('entries').setAttribute('aria-busy','false');$('archive-status').textContent=error.message;const a=el('a','返回栏目首页');a.href=route(target.section,roots[target.section]);$('entries').replaceChildren(a)}}
  function navigate(href){if(dialog.open)return;if(uploadBusy){alert('请等待本次上传结束，再切换目录。');return}history.pushState({},'',href);load();}
  document.addEventListener('click',event=>{const a=event.target.closest('a');if(!a||event.defaultPrevented||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey||a.hasAttribute('download'))return;const url=new URL(a.href);if(url.origin===location.origin&&url.pathname==='/archive'){event.preventDefault();navigate(url.pathname+url.search)}});
  window.addEventListener('popstate',()=>{if(dialog.open)dialog.close();load()});
  function editFolder(nextMode){if(!state?.canEdit)return;mode=nextMode;form.reset();if(mode==='edit'){form.elements.name.value=state.folder.name;form.elements.description.value=state.folder.description}$('folder-editor-title').textContent=mode==='edit'?'编辑目录与简介':'新建目录';$('folder-save').textContent=mode==='edit'?'保存修改':'创建目录';$('folder-save-status').textContent='';dialog.showModal()}
  function folderDirty(){return mode==='edit'?form.elements.name.value!==state.folder.name||form.elements.description.value!==state.folder.description:!!(form.elements.name.value||form.elements.description.value)}
  function closeFolder(){if(folderBusy)return;if(folderDirty()&&!confirm('有尚未保存的内容，确定放弃吗？'))return;dialog.close()}
  $('new-folder').addEventListener('click',()=>editFolder('create'));$('edit-folder').addEventListener('click',()=>editFolder('edit'));$('folder-close').addEventListener('click',closeFolder);$('folder-cancel').addEventListener('click',closeFolder);dialog.addEventListener('cancel',event=>{event.preventDefault();closeFolder()});
  form.addEventListener('submit',async event=>{event.preventDefault();if(folderBusy)return;folderBusy=true;for(const b of form.querySelectorAll('button'))b.disabled=true;const name=form.elements.name.value,description=form.elements.description.value;const target=state.folder;$('folder-save-status').textContent='正在保存…';try{await api(mode==='edit'?'/api/archive/folders/'+target.id:'/api/archive/folders',jsonOptions(mode==='edit'?'PATCH':'POST',mode==='edit'?{name,description,revision:target.revision}:{name,description,parentId:target.id}));dialog.close();await load()}catch(error){$('folder-save-status').textContent=error.message}finally{folderBusy=false;for(const b of form.querySelectorAll('button'))b.disabled=false}});
  window.addEventListener('beforeunload',event=>{if(uploadBusy||(dialog.open&&folderDirty())){event.preventDefault();event.returnValue=''}});
  function uploadStatus(item,text,kind){item.status=text;item.result=kind;item.statusNode.textContent=text;item.row.className='upload-item '+(kind||'');}
  function showPlan(items,target,folderMap){plan={items,target,folderMap};$('upload-panel').hidden=false;$('upload-items').replaceChildren();for(const item of items){item.row=el('li',undefined,'upload-item');item.row.append(el('span',item.path));item.statusNode=el('span','等待上传');item.row.append(item.statusNode);$('upload-items').append(item.row);item.result='pending'}$('upload-progress').value=0;$('retry-upload').hidden=true;}
  function summary(){const items=plan.items,done=items.filter(x=>x.result==='done').length,failed=items.filter(x=>x.result==='failed').length;$('upload-summary').textContent='已完成 '+done+' / '+items.length+' 项'+(failed?'，'+failed+' 项失败':'');$('upload-progress').value=items.length?(done+failed)/items.length*100:100;}
  function uploadFile(item,folder){return new Promise((resolve,reject)=>{const params=new URLSearchParams({folder,name:item.file.name,id:item.id,size:item.file.size});const xhr=new XMLHttpRequest();xhr.open('PUT','/api/archive/upload?'+params);xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.upload.onprogress=e=>{if(e.lengthComputable)uploadStatus(item,Math.round(e.loaded/e.total*100)+'% · 上传中','working')};xhr.upload.onload=()=>uploadStatus(item,'保存中…','working');xhr.onload=()=>{let data;try{data=JSON.parse(xhr.responseText)}catch{return reject(Error('服务器暂未响应，请重试。'))}xhr.status>=200&&xhr.status<300?resolve(data):reject(Error(data.error||'上传失败。'))};xhr.onerror=()=>reject(Error('网络中断，请重试。'));xhr.onabort=()=>reject(Error('上传已中断，请重试。'));xhr.send(item.file)})}
  async function runPlan(){if(uploadBusy||!plan)return;uploadBusy=true;for(const id of ['upload-files','upload-folder','new-folder'])$(id).disabled=true;$('retry-upload').hidden=true;const dirs=plan.folderMap;try{for(const item of plan.items){if(item.result==='done')continue;try{uploadStatus(item,item.kind==='folder'?'创建目录…':'准备上传…','working');const parent=dirs.get(item.parentPath);if(!parent)throw Error('上级目录未创建成功，请重试。');if(item.kind==='folder'){const data=await api('/api/archive/folders',jsonOptions('POST',{parentId:parent,name:item.name,description:'',reuseExisting:true}));dirs.set(item.path,data.entry.id);uploadStatus(item,data.reused?'目录已存在，保留原简介':'目录已建立','done')}else{if(item.file.size>52428800)throw Error('超过单个文件 50 MiB 的限制。');await uploadFile(item,parent);uploadStatus(item,'已保存','done')}}catch(error){uploadStatus(item,error.message,'failed')}summary()}}finally{uploadBusy=false;for(const id of ['upload-files','upload-folder','new-folder'])$(id).disabled=false;$('retry-upload').hidden=!plan.items.some(x=>x.result==='failed');summary();await load()}}
  function pathItems(files,emptyDirectories=[]){const directoryPaths=new Set(emptyDirectories);const fileItems=[];for(const file of files){const path=file.webkitRelativePath||file._archivePath||file.name;const parts=path.split('/');if(parts.some(p=>!p||p==='.'||p==='..'||p.includes('\\')))throw Error('选择的文件夹路径无效。');for(let i=1;i<parts.length;i++)directoryPaths.add(parts.slice(0,i).join('/'));fileItems.push({kind:'file',path,parentPath:parts.slice(0,-1).join('/'),file,id:crypto.randomUUID()})}const dirs=[...directoryPaths].sort((a,b)=>a.split('/').length-b.split('/').length||a.localeCompare(b)).map(path=>({kind:'folder',path,parentPath:path.split('/').slice(0,-1).join('/'),name:path.split('/').at(-1)}));return [...dirs,...fileItems]}
  async function startUpload(files,emptyDirectories=[]){if(uploadBusy||!state?.canEdit)return;try{const target=state.folder.id;const items=pathItems(files,emptyDirectories);if(!items.length){$('archive-status').textContent='没有选择可上传的文件或目录。';return}showPlan(items,target,new Map([['',target]]));await runPlan()}catch(error){$('archive-status').textContent=error.message}}
  $('upload-files').addEventListener('click',()=>{$('files-input').value='';$('files-input').click()});$('files-input').addEventListener('change',()=>startUpload([...$('files-input').files]));
  $('upload-folder').addEventListener('click',async()=>{if(uploadBusy||!state?.canEdit)return;if('showDirectoryPicker' in window){try{const handle=await window.showDirectoryPicker({mode:'read'});const files=[],dirs=[];async function walk(h,path){dirs.push(path);for await(const entry of h.values()){const relative=path+'/'+entry.name;if(entry.kind==='directory')await walk(entry,relative);else{const file=await entry.getFile();Object.defineProperty(file,'_archivePath',{value:relative});files.push(file)}}}await walk(handle,handle.name);await startUpload(files,dirs);return}catch(error){if(error.name==='AbortError')return;if(error.name!=='SecurityError'&&error.name!=='NotAllowedError'){ $('archive-status').textContent='无法读取所选目录：'+error.message;return}}}$('folder-input').value='';$('folder-input').click()});
  $('folder-input').addEventListener('change',()=>{if($('folder-input').files.length)startUpload([...$('folder-input').files]);else $('archive-status').textContent='未选到文件。这个浏览器不能读取空目录，可用“新建目录”建立。'});
  $('retry-upload').addEventListener('click',runPlan);
  load();
})();
